import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useApi } from '@/lib/api/api-provider'
import type { Page } from '@/lib/api/types'
import type { Customer, CustomerInput } from './types'

const PATH = '/api/shop/customers'
const KEY = ['shop', 'customer'] as const

export interface CustomerFilters {
  q?: string
  page?: number
  size?: number
  sort?: string
}

const item = (id: number) => `${PATH}/${encodeURIComponent(String(id))}`

export function useCustomerList(filters: CustomerFilters) {
  const api = useApi()
  return useQuery({
    queryKey: [...KEY, filters],
    queryFn: () => api.get<Page<Customer>>(PATH, { ...filters }),
    placeholderData: previous => previous,
  })
}

export function useSaveCustomer() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, input }: { id?: number; input: CustomerInput }) =>
      id != null ? api.put<Customer>(item(id), input) : api.post<Customer>(PATH, input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}

export function useDeleteCustomer() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (id: number) => api.delete(item(id)),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}
